package com.bank.partial.repository;

import com.bank.partial.model.Loan;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.time.LocalDateTime;
import java.util.List;

public interface LoanRepository extends JpaRepository<Loan, String> {

    // Predicate INCLUDES status='PENDING' → planner can use ix_pending_loans
    @Query("SELECT l FROM Loan l WHERE l.status = 'PENDING' AND l.appliedAt < :before " +
           "ORDER BY l.appliedAt")
    List<Loan> pendingOlderThan(@Param("before") LocalDateTime before);

    // Soft-delete query → matches ix_live_loans (WHERE deleted = false)
    @Query("SELECT l FROM Loan l WHERE l.accountId = :accountId AND l.deleted = false")
    List<Loan> liveLoansForAccount(@Param("accountId") String accountId);
}
