package com.bank.partial.service;

import com.bank.partial.model.Loan;
import com.bank.partial.repository.LoanRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class LoanReviewService {
    private static final Logger log = LoggerFactory.getLogger(LoanReviewService.class);
    private final LoanRepository repo;

    public LoanReviewService(LoanRepository repo) { this.repo = repo; }

    public List<Loan> pendingForReview(LocalDateTime before) {
        log.info("Listing PENDING loans older than {} via tiny partial index ix_pending_loans",
                 before);
        return repo.pendingOlderThan(before);
    }

    public List<Loan> liveLoans(String accountId) {
        log.info("Live (not deleted) loans for {} via partial index ix_live_loans", accountId);
        return repo.liveLoansForAccount(accountId);
    }
}
